from pathlib import Path
p=Path('index.html')
s=p.read_text(encoding='utf-8')
s=s.replace("async function load(){await loadNLTA();await loadOSM()}","async function load(){await loadNLTA();loadOSM()}",1)
s=s.replace("if(!routes.length)await load();","if(!routes.length){$('result').innerHTML='<b>🚌 Chargement du réseau…</b><div class=\"small\">MauriMove charge les lignes et arrêts. Je ne vais pas laisser l’écran bloqué indéfiniment.</div>';try{await Promise.race([loadOSM(),new Promise((_,rej)=>setTimeout(()=>rej(Error('network-timeout')),20000))])}catch(e){$('result').innerHTML='<b>Le réseau bus met trop de temps à répondre.</b><div class=\"small\">La recherche de lieux fonctionne toujours. Réessaie le trajet dans quelques secondes.</div>';return finish()}}",1)
s=s.replace("async function draw(points){clear();const fallback=L.polyline(points,{color:'#0072CE',weight:5,opacity:.6}).addTo(map);marks.push(fallback);try{const j=await get(ROAD+points.map(p=>p[1]+','+p[0]).join(';')+'?overview=full&geometries=geojson&steps=false');const c=j.routes?.[0]?.geometry?.coordinates;if(c){fallback.remove();const ll=c.map(p=>[p[1],p[0]]);marks.push(L.polyline(ll,{color:'#0072CE',weight:5}).addTo(map));map.fitBounds(ll,{padding:[70,70]});return}}catch(e){}map.fitBounds(points,{padding:[70,70]})}","async function draw(points){clear();try{const j=await get(ROAD+points.map(p=>p[1]+','+p[0]).join(';')+'?overview=full&geometries=geojson&steps=false');const c=j.routes?.[0]?.geometry?.coordinates;if(!c)throw Error('NoRoute');const ll=c.map(p=>[p[1],p[0]]);marks.push(L.polyline(ll,{color:'#0072CE',weight:6,lineCap:'round',lineJoin:'round'}).addTo(map));map.fitBounds(ll,{padding:[70,70]});return true}catch(e){marks.push(L.polyline(points,{color:'#FFD500',weight:4,dashArray:'8 8'}).addTo(map));map.fitBounds(points,{padding:[70,70]});return false}}",1)
p.write_text(s,encoding='utf-8')
print('runtime patch applied')
